import { transform } from 'sucrase'

export type RuntimeSourceMode = 'exec' | 'preflight' | 'inspect' | 'defineJob' | 'deployApp'

export interface PreparedRuntimeSource {
  readonly code: string
  readonly transformed: boolean
  readonly mode: RuntimeSourceMode
  readonly error?: string | undefined
}

export function stripRuntimeTypescript(
  code: string,
  mode: RuntimeSourceMode
): PreparedRuntimeSource {
  try {
    return {
      code: transform(code, {
        transforms: ['typescript'],
        production: true,
      }).code,
      transformed: true,
      mode,
    }
  } catch (error) {
    return {
      code,
      transformed: false,
      mode,
      error: error instanceof Error ? error.message : String(error),
    }
  }
}

export function prepareRuntimeSource(code: string, mode: RuntimeSourceMode): PreparedRuntimeSource {
  return stripRuntimeTypescript(code, mode)
}
